window.RP_SESSION={"id":"S-be29116de5ef","messages":[{"id":"RP-III-0134481","time":"2026-08-04T21:35:00+09:00","room":"RP III","name":"올리브","profile":"올리브","identity":"reviewed","type":"dialogue","body":" \"올리브, 사랑은 있잖아.\"","characters":["P-6ba6a097816f"]},{"id":"RP-III-0134482","time":"2026-08-04T21:36:00+09:00","room":"RP III","name":"올리브","profile":"올리브","identity":"reviewed","type":"dialogue","body":" \"사랑은 있잖아. 사랑으로만 이어나갈 수 있는게 아니야.\"","characters":["P-6ba6a097816f"]},{"id":"RP-III-0134483","time":"2026-08-04T21:36:00+09:00","room":"RP III","name":"올리브","profile":"올리브","identity":"reviewed","type":"dialogue","body":" \"사랑만이 할 수 있는 일이 있는거잖아.\"","characters":["P-6ba6a097816f"]},{"id":"RP-III-0134484","time":"2026-08-04T21:36:00+09:00","room":"RP III","name":"올리브","profile":"올리브","identity":"reviewed","type":"dialogue","body":"  그렇지...?","characters":["P-6ba6a097816f"]},{"id":"RP-III-0134485","time":"2026-08-04T21:37:00+09:00","room":"RP III","name":"올리브","profile":"올리브","identity":"reviewed","type":"dialogue","body":" \"세상의 모든 것은 할 수 있는것과 할 수 없는 것이 정해져있어. 올리브, 너도 이제 열 일곱 살이잖아.\"","characters":["P-6ba6a097816f"]},{"id":"RP-III-0134486","time":"2026-08-04T21:38:00+09:00","room":"RP III","name":"올리브","profile":"올리브","identity":"reviewed","type":"dialogue","body":" 올리브는 한숨을 내쉬었다. 불만이 있어서가 아니었다. 그저, 숨이 잘 쉬어지지 않았다.","characters":["P-6ba6a097816f"]},{"id":"RP-III-0134487","time":"2026-08-04T21:39:00+09:00","room":"RP III","name":"올리브","profile":"올리브","identity":"reviewed","type":"dialogue","body":"그래서 내쉰 한숨이었다. 계속해서 새로운 숨을 쉬고 있는 지금도 그것이 올리브의 마지막 한 숨처럼만 느껴졌다.","characters":["P-6ba6a097816f"]},{"id":"RP-III-0134488","time":"2026-08-04T21:41:00+09:00","room":"RP III","name":"올리브","profile":"올리브","identity":"reviewed","type":"dialogue","body":" 올리브는 자신의 이름이 좋았다. 그 아이의 입이 자신이 이름을 발음하는 것이 좋았다. 그 아이가 불러주는 자신의 이름이 좋았다.","characters":["P-6ba6a097816f"]},{"id":"RP-III-0134489","time":"2026-08-04T21:41:00+09:00","room":"RP III","name":"올리브","profile":"올리브","identity":"reviewed","type":"dialogue","body":"... ... ...","characters":["P-6ba6a097816f"]},{"id":"RP-III-0134490","time":"2026-08-04T21:41:00+09:00","room":"RP III","name":"올리브","profile":"올리브","identity":"reviewed","type":"dialogue","body":"뭐, 이제는 중요하지 않으려나.","characters":["P-6ba6a097816f"]},{"id":"RP-III-0134491","time":"2026-08-04T21:42:00+09:00","room":"RP III","name":"올리브","profile":"올리브","identity":"reviewed","type":"dialogue","body":" 사랑은 사랑만으로 이어질 수 있는게 아니다. 올리브가 아주 비싼 값을 치른 교훈이었다.","characters":["P-6ba6a097816f"]},{"id":"RP-III-0134492","time":"2026-08-04T21:43:00+09:00","room":"RP III","name":"올리브","profile":"올리브","identity":"reviewed","type":"dialogue","body":" 돈만 있으면 사람도 살 수 있어. 올리브가 그보다 훨씬 전에 알았던 교훈이다.","characters":["P-6ba6a097816f"]},{"id":"RP-III-0134493","time":"2026-08-04T21:43:00+09:00","room":"RP III","name":"올리브","profile":"올리브","identity":"reviewed","type":"dialogue","body":"그런 당연한 이야기들을, 그 나이 먹고야 깨닫다니. 깨닫고 나서도 제대로 소화시키지 못하다니.","characters":["P-6ba6a097816f"]},{"id":"RP-III-0134494","time":"2026-08-04T21:43:00+09:00","room":"RP III","name":"올리브","profile":"올리브","identity":"reviewed","type":"dialogue","body":" 우습네.","characters":["P-6ba6a097816f"]},{"id":"RP-III-0134495","time":"2026-08-04T21:44:00+09:00","room":"RP III","name":"올리브","profile":"올리브","identity":"reviewed","type":"dialogue","body":" 어른이 된 지금에 와서는 바보같게만 느껴지는, 그런 어린 이야기일 뿐이었다.","characters":["P-6ba6a097816f"]},{"id":"RP-III-0134496","time":"2026-08-04T21:45:00+09:00","room":"RP III","name":"올리브","profile":"올리브","identity":"reviewed","type":"dialogue","body":"   그런데여전히사랑만이가능한일이있어서.닳고닳아도계속유지할수있게되는그러힘이.","characters":["P-6ba6a097816f"]},{"id":"RP-III-0134497","time":"2026-08-04T21:46:00+09:00","room":"RP III","name":"올리브","profile":"올리브","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-6ba6a097816f"]},{"id":"RP-III-0134498","time":"2026-08-04T21:46:00+09:00","room":"RP III","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"...good for you.","characters":[]}]}